def hms_to_seconds(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)

def dhms_to_seconds(s):
    dpart, rest = s.split("d ")
    h, m, sec = rest.split(":")
    return int(dpart) * 86400 + int(h) * 3600 + int(m) * 60 + int(sec)

def hms_to_seconds_signed(s):
    sign = -1 if s.startswith("-") else 1
    s = s.lstrip("-")
    h, m, sec = s.split(":")
    return sign * (int(h) * 3600 + int(m) * 60 + int(sec))

def clock_to_millis(s):
    time_part, ms_part = s.split(".")
    m, sec = time_part.split(":")
    return (int(m) * 60 + int(sec)) * 1000 + int(ms_part)

def age_in_years_months(birth, today):
    by, bm, bd = birth
    ty, tm, td = today
    months_total = (ty - by) * 12 + (tm - bm)
    if td < bd:
        months_total -= 1
    years = months_total // 12
    months = months_total % 12
    return (years, months)

def years_months_days_between(d1, d2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
    y1, m1, dd1 = d1
    y2, m2, dd2 = d2
    days = dd2 - dd1
    months = m2 - m1
    years = y2 - y1
    if days < 0:
        pm = m2 - 1
        py = y2
        if pm == 0:
            pm = 12
            py -= 1
        days += dim(py, pm)
        months -= 1
    if months < 0:
        months += 12
        years -= 1
    return (years, months, days)

def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim_list(y):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def doy(y, m, d):
        return sum(dim_list(y)[:m - 1]) + d
    def days_in_year(y):
        return 366 if is_leap(y) else 365
    m, d = birth_md
    y, tm, td = today_ymd
    today_doy = doy(y, tm, td)
    bday_doy = doy(y, m, d)
    if bday_doy >= today_doy:
        return bday_doy - today_doy
    return (days_in_year(y) - today_doy) + doy(y + 1, m, d)

def is_birthday_today(birth_md, today_ymd):
    y, m, d = today_ymd
    return (m, d) == birth_md

def next_birthday_year(birth_md, today_ymd):
    m, d = birth_md
    y, tm, td = today_ymd
    if (tm, td) <= (m, d):
        return y
    return y + 1

def is_older(birth1, birth2):
    if birth1 < birth2:
        return "first"
    elif birth2 < birth1:
        return "second"
    return "same"

def age_difference_in_years(birth1, birth2, today):
    def age(birth):
        by, bm, bd = birth
        ty, tm, td = today
        y = ty - by
        if (tm, td) < (bm, bd):
            y -= 1
        return y
    return age(birth1) - age(birth2)
